"use strict";function rgbToHsv(a,r,t){a/=255,r/=255,t/=255;var e=Math.max(a,r,t),o=Math.min(a,r,t),n=e,s=e,u=e-o,c=0===e?0:u/e;if(e===o)n=0;else{switch(e){case a:n=(r-t)/u+(t>r?6:0);break;case r:n=(t-a)/u+2;break;case t:n=(a-r)/u+4}n/=6}return{h:n,s:c,v:s}}function hsvToRgb(a,r,t){a*=6;var e=Math.floor(a),o=a-e,n=t*(1-r),s=t*(1-o*r),u=t*(1-(1-o)*r),c=e%6,h=[t,s,n,n,u,t][c],i=[u,t,t,s,n,n][c],v=[n,n,u,t,t,s][c];return{r:255*h,g:255*i,b:255*v}}function compareHue(a,r){return a.h-r.h}function compareSaturation(a,r){return a.s-r.s}function compareValue(a,r){return a.v-r.v}function sortPixels(a,r){var t,e,o=[];o.length=a.data.length/4;var n=0;for(t=0,e=a.data.length;e>t;t+=4){var s=a.data[t],u=a.data[t+1],c=a.data[t+2];o[n]=rgbToHsv(s,u,c),n++}if("hue"===r)o.sort(compareHue);else if("saturation"===r)o.sort(compareSaturation);else{if("value"!==r)throw new Error("Unknown sort method "+r);o.sort(compareValue)}for(n=0,t=0,e=a.data.length;e>t;t+=4){var h=o[n],i=hsvToRgb(h.h,h.s,h.v);n++,a.data[t]=i.r,a.data[t+1]=i.g,a.data[t+2]=i.b}}